displayReferred.invertAcesFilmicSource:
function invertAcesFilmic(t) {
  const z = clamp(acesOutputInverse.mul(t), vec3(0.0), vec3(DISPLAY_CLAMP))
  const a = z.mul(0.983729).sub(1.0)
  const b = z.mul(0.983729 * 0.4329510).sub(0.0245786)
  const c = z.mul(0.238081).add(0.000090537)
  const y = b.negate().sub(sqrt(max(b.mul(b).sub(a.mul(c).mul(4.0)), vec3(0.0)))).div(a.mul(2.0))
  return acesInputInverse.mul(y).mul(float(0.6).div(toneMappingExposure))
}

displayReferred.sceneLinearToDisplayReferredSource:
export function sceneLinearToDisplayReferred(linear) {
  const mapped = select(toneMappingMode.equal(TONE_MAPPING_ACES), acesFilmicToneMapping(linear, toneMappingExposure), linear)
  return sRGBTransferOETF(clamp(mapped, vec3(0.0), vec3(1.0)))
}

displayReferred.displayReferredToSceneLinearSource:
export function displayReferredToSceneLinear(display) {
  const t = clamp(srgbToLinear(display), vec3(0.0), vec3(DISPLAY_CLAMP))
  return select(toneMappingMode.equal(TONE_MAPPING_ACES), invertAcesFilmic(t), t)
}
